import{_ as t,c as r,o as a,ah as l}from"./chunks/framework.PvdZnrZd.js";const u=JSON.parse('{"title":"Order Fulfillment","description":"Order Fulfillment","frontmatter":{"title":"Order Fulfillment","description":"Order Fulfillment","author":"Chirag Tyagi"},"headers":[],"relativePath":"zenith/order/order-fulfillment.md","filePath":"zenith/order/order-fulfillment.md"}'),o={name:"zenith/order/order-fulfillment.md"};function i(n,e,p,s,h,d){return a(),r("div",null,[...e[0]||(e[0]=[l('<h2 id="let-s-see-how-orders-can-be-fulfilled-in-the-multi-vendor-marketplace-for-shopify" tabindex="-1">Let&#39;s see how orders can be fulfilled in the Multi-Vendor Marketplace for Shopify <a class="header-anchor" href="#let-s-see-how-orders-can-be-fulfilled-in-the-multi-vendor-marketplace-for-shopify" aria-label="Permalink to &quot;Let&#39;s see how orders can be fulfilled in the Multi-Vendor Marketplace for Shopify&quot;">​</a></h2><p>In <a href="/zenith/introduction/">Multi-Vendor Marketplace</a>, once the order is being placed from the Shopify store then each seller can do the fulfillment of their respective products directly from their seller panel on the app.</p><p>But, we do give the Admin an option to restrict his Sellers from fulfilling the orders. In other words, if the admin doesn&#39;t want his sellers to fulfill the orders &amp; instead he wants to fulfill the order then he can do so in the Multivendor Marketplace.</p><h2 id="let-s-catch-each-scenario-one-by-one" tabindex="-1">Let&#39;s catch each scenario one by one: <a class="header-anchor" href="#let-s-catch-each-scenario-one-by-one" aria-label="Permalink to &quot;Let&#39;s catch each scenario one by one:&quot;">​</a></h2><p>The Admin can configure whether he wants his Sellers to fulfill orders or not.</p><p>To configure this in the MultiVendor Marketplace app, the Admin needs to visit his MultiVendor Marketplace Admin Panel &gt; Configuration &gt; Seller Configuration:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/allowsellertoflfillitem.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/allowsellertoflfillitem.webp" alt="Configuration Admin"></a></p><h2 id="case-i" tabindex="-1">CASE: I <a class="header-anchor" href="#case-i" aria-label="Permalink to &quot;CASE: I&quot;">​</a></h2><p><strong>Admin wants the orders to be fulfilled by the Sellers.</strong></p><p>So in this case, whenever an order gets placed, the Seller will fulfill &amp; mark the order as delivered from his end.</p><p>MultiVendor Marketplace Seller Panel &gt; Orders &gt; Order Listing &gt; View:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/proceedtofulfillorder-1.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/proceedtofulfillorder-1.webp" alt="Order Details Seller • Multivendor MarketPlace (3)"></a></p><p>Clicking on the &#39;Fulfill&#39; button, a pop-up will generate where the Seller needs to enter the tracking number, tracking URL &amp; shipping method and then click on &#39;Fulfill items&#39;:</p><blockquote><p>The tracking number &amp; URL will be given by the shipment provider.</p></blockquote><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/fulfillmentmethodtrckdetails.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/fulfillmentmethodtrckdetails.webp" alt="Order-Details-Seller-•-Multivendor-MarketPlace-5"></a></p><p>The admin can make the tracking number &amp; shipping methods as mandatory details, i.e., the seller mandatorily has to enter these details before fulfilling the order.</p><p>To configure this, Admin needs to go to MultiVendor Marketplace Admin Panel &gt; Order Configuration:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/mandateordertrackingdeyails.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/mandateordertrackingdeyails.webp" alt="Configuration Admin (1)"></a></p><p>After fulfilling, the Seller can either edit tracking details or enter delivery details:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/editrackingdeliverydetails.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/editrackingdeliverydetails.webp" alt="Order Details Seller • Multivendor MarketPlace (5)"></a></p><p>Check the box in front of Delivery Status to mark the order as delivered:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/deloverystatus.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/deloverystatus.webp" alt="Order Details Seller • Multivendor MarketPlace (7)"></a></p><p>The Seller can generate a shipping label from the <strong>Additional Order Details</strong> section only before he marks the order as delivered, after that he&#39;ll only be able to generate just the customer invoice.</p><p>Multivendor Marketplace App has some shipping feature apps which will allow you to ship orders &amp; generate shipping labels. Dropping them down:</p><h2 id="shipstation" tabindex="-1">ShipStation <a class="header-anchor" href="#shipstation" aria-label="Permalink to &quot;ShipStation&quot;">​</a></h2><p><strong><a href="https://www.shipstation.com/" target="_blank" rel="noreferrer">ShipStation</a></strong> is a web-based, multi-carrier shipping solution for ecommerce retailers. Designed to streamline the fulfillment process.</p><p>This feature will allow you to ship your goods via multiple carrier shipping methods. Moreover, you can automatically generate shipping labels. <a href="/zenith/featured-app/shipping/shipstation.html">Know More.</a></p><h2 id="blue-dart" tabindex="-1">Blue Dart <a class="header-anchor" href="#blue-dart" aria-label="Permalink to &quot;Blue Dart&quot;">​</a></h2><p>You can now allow sellers to fulfill orders via Blue Dart fulfillment &amp; courier delivery services. Additionally, allow sellers to generate shipping labels for fulfilled orders. <a href="/zenith/featured-app/shipping/bluedart.html">Know More.</a></p><h2 id="ups" tabindex="-1">UPS <a class="header-anchor" href="#ups" aria-label="Permalink to &quot;UPS&quot;">​</a></h2><p>Enable the “UPS” feature app to let the sellers ship their products through UPS. <a href="/zenith/featured-app/shipping/ups-shipping.html">Know More.</a></p><h2 id="vamaship" tabindex="-1">Vamaship <a class="header-anchor" href="#vamaship" aria-label="Permalink to &quot;Vamaship&quot;">​</a></h2><p>Using this featured app, the merchants can enable shipment through Vamaship. Moreover, he can automatically generate shipping labels for the same. <a href="/zenith/featured-app/shipping/vamaship.html">Know More.</a></p><h2 id="fedex" tabindex="-1">FedEx <a class="header-anchor" href="#fedex" aria-label="Permalink to &quot;FedEx&quot;">​</a></h2><p>Using this featured app, the merchants can enable shipment through <strong>FedEx</strong>. Moreover, he can allow <strong>US</strong> <strong>sellers</strong> to automatically generate shipping labels. <a href="/zenith/featured-app/shipping/fedex-shipping.html">Know More.</a></p><h2 id="ecom-express" tabindex="-1">Ecom Express <a class="header-anchor" href="#ecom-express" aria-label="Permalink to &quot;Ecom Express&quot;">​</a></h2><p>his feature will help both the admin and the seller to manage the fulfillment in the best possible way. Once the customer places an order, the seller can directly fulfill it from the backend with the help of the Ecom Express Shipping feature. <a href="/zenith/featured-app/shipping/ecom-express-shipping.html">Know More.</a></p><h2 id="canada-post-shipping" tabindex="-1"><strong>Canada Post Shipping</strong> <a class="header-anchor" href="#canada-post-shipping" aria-label="Permalink to &quot;**Canada Post Shipping**&quot;">​</a></h2><p>Admin can allow his sellers of Canada to ship their products worldwide and also generate a “shipping label” from their panel. <a href="/zenith/featured-app/shipping/canada-post-shipping.html">Know More</a>.</p><h2 id="australia-post-shipping" tabindex="-1"><strong>Australia Post Shipping</strong> <a class="header-anchor" href="#australia-post-shipping" aria-label="Permalink to &quot;**Australia Post Shipping**&quot;">​</a></h2><p>The Admin can let his sellers ship the orders via Australia post shipping method and can even generate shipping labels using the app. <a href="/zenith/featured-app/shipping/australia-post-shipping.html">Know More</a>.</p><h2 id="airspeed-shipping" tabindex="-1"><strong>AirSpeed Shipping</strong> <a class="header-anchor" href="#airspeed-shipping" aria-label="Permalink to &quot;**AirSpeed Shipping**&quot;">​</a></h2><p>Using this featured app, Both the admin and sellers can notify the courier about the customer’s order from their respective panels. Also, Sellers will manage fulfillment and can generate shipping labels for fulfilled orders. <a href="/zenith/featured-app/shipping/air-speed-shipping.html">Know More</a>.</p><h2 id="case-ii" tabindex="-1">CASE: II <a class="header-anchor" href="#case-ii" aria-label="Permalink to &quot;CASE: II&quot;">​</a></h2><p><strong>Admin doesn&#39;t want the Sellers to fulfill their orders, instead, he will fulfill the orders by himself.</strong></p><p>Now, the seller will not get any option to fulfill the order (as shown in the image below) whenever a customer places an order.</p><p>MultiVendor Marketplace Seller Panel &gt; Orders &gt; Order Listing &gt; View:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/additionalorderdetails.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/additionalorderdetails.webp" alt="Order Details Seller • Multivendor MarketPlace"></a></p><p>The seller can only generate a customer invoice from the Order Details section.</p><p>Coming to the Admin end, he can fulfill the order from Shopify backend.</p><p>Shopify Backend &gt; Orders &gt; All Orders &gt; Click on the order ID:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/05/multivendor-marketplace-4-Orders-Shopify.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/05/multivendor-marketplace-4-Orders-Shopify.png" alt="multivendor marketplace 4 Orders Shopify"></a></p><p>On this page, the Admin will capture the payment &amp; mark the order as fulfilled.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/05/multivendor-marketplace-4-Orders-1038-Shopify.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/05/multivendor-marketplace-4-Orders-1038-Shopify.png" alt="multivendor marketplace 4 Orders 1038 Shopify"></a></p><p>After clicking on the &#39;Mark as fulfilled&#39; button, the Admin needs to enter the tracking number &amp; shipping carrier. These are optional fields.</p><p>If the Admin is using a carrier other than Shopify Shipping, then he needs to enter the tracking number given by his shipping provider. The tracking URL will appear in the customer&#39;s shipping confirmation and shipping update emails.</p><p>To send the shipping information to your customers right after the fulfillment, check the &#39;Send shipment details to your customers now&#39; option.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/05/multivendor-marketplace-4-Fulfillment-Shopify.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/05/multivendor-marketplace-4-Fulfillment-Shopify.png" alt="multivendor marketplace 4 Fulfillment Shopify"></a></p><p>The fulfillment details will auto-update on both Admin &amp; Seller Panel.</p><h2 id="admin-panel" tabindex="-1">Admin Panel: <a class="header-anchor" href="#admin-panel" aria-label="Permalink to &quot;Admin Panel:&quot;">​</a></h2><p>MultiVendor Marketplace Admin Panel &gt; Orders &gt; Order Listing &gt; View:</p><p>Furthermore, admin can only generate an invoice or raise RMA request now-</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/additionalorderdetails.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/additionalorderdetails.webp" alt="Order Details Admin"></a></p><p>Whereas, the Seller can mark the order as delivered, print customer invoice &amp; generate shipping labels:</p><p>MultiVendor Marketplace Seller Panel &gt; Orders &gt; Order Listing &gt; View:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/additionalorderdetails.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/additionalorderdetails.webp" alt="Order Details Seller • Multivendor MarketPlace (2)"></a></p><h2 id="case-iii" tabindex="-1">CASE: III <a class="header-anchor" href="#case-iii" aria-label="Permalink to &quot;CASE: III&quot;">​</a></h2><p><strong>If the Admin doesn&#39;t want the Sellers to fulfill the order when the order has a high risk of fraud.</strong></p><p>Then, in this case, The Admin can enable this tab, to restrict Seller to fulfillment for fraud orders whose fraud risk is high.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/restrictsellerfraudorder.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/restrictsellerfraudorder.webp" alt="configuration"></a></p><p><a href="/zenith/order/fraud-analysis.html">For more information check the below reference </a></p><p>This was all about the Order Fulfillment in MultiVendor Marketplace App.</p><h3 id="demo-details" tabindex="-1">Demo Details <a class="header-anchor" href="#demo-details" aria-label="Permalink to &quot;Demo Details&quot;">​</a></h3><p>Check out: <a href="https://multivendor-marketplace-5.myshopify.com/pages/seller-profile" target="_blank" rel="noreferrer">https://multivendor-marketplace-5.myshopify.com/pages/demo</a></p>',74)])])}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
